// Reemplaza cada [AUDIO n] por su texto, en el mismo lugar de la conversación.
const transcript = $('Armar transcripción').first().json;
if (!transcript.audios.length) {
  return [{ json: { ...transcript, audioProblem: null, audioFailures: 0 }, pairedItem: { item: 0 } }];
}
const sources = $('Separar audios').all();
const results = $input.all();
let text = transcript.transcript;
let failures = 0;
sources.forEach((source, index) => {
  const response = results[index]?.json || {};
  const spoken = response.statusCode === 200 ? String(response.body?.text || '').trim() : '';
  const key = source.json.key;
  if (spoken) {
    text = text.replace(`[${key}]`, `[${key} - nota de voz transcrita]: ${spoken}`);
  } else {
    failures += 1;
    text = text.replace(`[${key}]`, `[${key} - nota de voz que no se pudo transcribir]`);
  }
});
return [{ json: {
  ...transcript,
  transcript: text,
  audioFailures: failures,
  audioProblem: failures ? `${failures} de ${sources.length} notas de voz no se pudieron transcribir; escúchalas en la conversación` : null,
}, pairedItem: { item: 0 } }];

// OpenAI reconoce el formato por la extensión del nombre: WhatsApp manda .opus/.oga o URLs sin extensión.
const SUPPORTED = /\.(?:flac|mp3|mp4|mpeg|mpga|m4a|ogg|wav|webm)$/i;
const byMime = { 'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a', 'audio/aac': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm', 'video/mp4': 'mp4' };
return $input.all().map((item, index) => {
  const file = item.binary?.audio;
  if (file && !SUPPORTED.test(file.fileName || '')) {
    const mime = String(file.mimeType || '').split(';')[0].trim().toLowerCase();
    file.fileName = `nota-de-voz-${index + 1}.${byMime[mime] || 'ogg'}`;
    if (!byMime[mime]) file.mimeType = 'audio/ogg';
  }
  return { json: item.json, binary: item.binary, pairedItem: { item: index } };
});

const transcript = $('Armar transcripción').first().json;
const response = $input.first().json;
if (!transcript.imageUrls.length) {
  return [{ json: { imageText: '', visualStatus: 'not_needed', visualProblem: null } }];
}

let imageText = '';
let visualProblem = null;
if (response.statusCode !== 200) {
  visualProblem = `OpenAI visual respondió ${response.statusCode || "sin estado"}`;
} else {
  try {
    const rawContent = response.body?.choices?.[0]?.message?.content;
    const parsed = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
    imageText = String(parsed?.imageText || '').trim();
    if (!imageText) visualProblem = 'La lectura visual no devolvió texto';
  } catch (error) {
    visualProblem = 'La lectura visual no devolvió JSON válido';
  }
}
return [{ json: { imageText, visualStatus: visualProblem ? 'failed' : 'extracted', visualProblem } }];

