={{ (() => {
  const transcript = $('Armar transcripción').item.json;
  const instruction = 'Transcribe fielmente todo el texto legible de estas imágenes de una lista de mercado. Devuelve todos los renglones de productos en el orden visible. Conserva ortografía, cantidades, unidades, marcas, presentaciones, precios escritos y anotaciones; no normalices ni corrijas productos. Si una parte no es segura, márcala como [lectura dudosa: ...]. No inventes texto. Si hay varias imágenes, separa su contenido con IMAGEN 1, IMAGEN 2, etc.';
  const content = [{ type: 'text', text: instruction }, ...transcript.imageUrls.map((url) => ({ type: 'image_url', image_url: { url, detail: 'high' } }))];
  const responseSchema = { type: 'object', additionalProperties: false, required: ['imageText'], properties: { imageText: { type: 'string' } } };
  return JSON.stringify({ model: $('Config').item.json.OPENAI_MODEL, messages: [{ role: 'user', content }], response_format: { type: 'json_schema', json_schema: { name: 'transcripcion_imagenes', strict: true, schema: responseSchema } } });
})() }}

