const response = .first().json;
const status = response.statusCode;
const body = response.body || {};
const ok = status >= 200 && status < 300 && Boolean(body.order_number);
return [{ json: {
  ok,
  status,
  adjusted: ok && body.adjusted === true,
  mode: body.adjusted ? 'updated' : 'created',
  orderNumber: body.order_number || null,
  duplicate: status === 409,
  afterCutoff: false,
  scheduledFor: null,
  scheduledForLabel: null,
  error: ok ? null : (body.error || `La app respondió `),
} }];

const input = $('Normalizar entrada').first().json;
const transcript = $('Contexto de audio').first().json;
const visual = $('Contexto visual').first().json;
const conversation = $('Buscar conversación GHL').first().json;
const conversationId = conversation?.body?.conversations?.[0]?.id || null;

let extracted = $input.first().json.output ?? null;
let problem = null;
let ignored = false;
if (typeof extracted === 'string') {
  try { extracted = JSON.parse(extracted); }
  catch (error) { problem = 'El modelo principal no devolvió JSON válido'; }
}
if (transcript.readStatus !== 200) problem = `GHL respondió ${transcript.readStatus} al leer la conversación`;
// Un nuevo llamado sin mensajes nuevos del cliente (repetido o de respaldo) no es un error.
else if (!transcript.inboundMessages) { problem = 'El cliente no ha escrito nada nuevo'; ignored = true; }
if (!problem && transcript.imageUrls.length && visual.visualProblem) problem = visual.visualProblem;
if (!problem && !extracted) problem = 'El modelo principal no devolvió un pedido válido';
if (!problem && extracted && !extracted.ok) {
  problem = extracted.error || 'La conversación de hoy no contiene un pedido';
  // Con una nota de voz sin transcribir no se puede afirmar que no hay pedido: se pide ayuda.
  if (transcript.audioProblem) problem = `${transcript.audioProblem}. ${problem}`;
  else ignored = true;
}
const rawOrderText = String(extracted?.rawOrderText || '').trim();
const numericValue = (value) => {
  const compact = String(value).replace(/\s/g, '');
  if (/^\d{1,3}(?:\.\d{3})+$/.test(compact)) return Number(compact.replace(/\./g, ''));
  if (/^\d{1,3}(?:,\d{3})+$/.test(compact)) return Number(compact.replace(/,/g, ''));
  return Number(compact.replace(',', '.'));
};
// items es solo un índice operativo requerido por la app. El pedido real y completo es rawOrderText.
const items = rawOrderText.split(/\r?\n|;+/).map((line) => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').trim()).filter(Boolean).slice(0, 100).map((rawLine) => {
  const rawText = rawLine.slice(0, 500);
  const byAmount = rawLine.match(/^\$?\s*([\d.,]+)\s*(mil|k)?\s*(?:pesos?)?\s+de\s+(.+)$/i);
  if (byAmount) {
    let amount = numericValue(byAmount[1]);
    if (byAmount[2] && amount < 1000) amount *= 1000;
    const monetary = Boolean(byAmount[2]) || amount >= 1000 || rawLine.startsWith('$');
    if (monetary) return { name: byAmount[3].trim().slice(0, 160), quantity: amount, unit: 'COP', quantityKind: 'amount', rawText };
  }
  return { name: rawLine.slice(0, 160), quantity: 1, rawText };
});
if (!problem && !rawOrderText) problem = 'La extracción no produjo el texto completo del pedido';
if (!problem && !items.length) problem = 'El texto del pedido no contiene líneas utilizables';

// Con pedido abierto se anexa salvo que el cliente pida explícitamente otro pedido. Sin pedido
// abierto siempre se crea uno nuevo. Si la app no respondió se conserva el ajuste anterior.
const orderAction = transcript.openOrder
  ? (extracted?.action === 'nuevo' ? 'new' : 'update')
  : (transcript.contextOk ? 'new' : 'update');
const notes = [extracted?.notes, transcript.audioProblem ? `⚠️ ${transcript.audioProblem}` : null]
  .map((value) => String(value || '').trim()).filter(Boolean).join(' · ');
const name = String(extracted?.customer?.name || input.contactName || '').trim();
const phone = String(extracted?.customer?.phone || input.contactPhone || '').trim();
const address = String(extracted?.delivery?.address || input.contactAddress || '').trim();
const delivery = extracted?.delivery?.type === 'recogida' ? { type: 'recogida' } : { type: 'domicilio', ...(address ? { address } : {}) };
return [{ json: {
  valid: !problem,
  ignored,
  problem,
  conversationId,
  idempotencySeed: transcript.idempotencySeed,
  summaryText: rawOrderText,
  payload: {
    locationId: input.locationId,
    contactId: input.contactId,
    conversationId: conversationId || undefined,
    customer: { name: name || undefined, phone: phone || undefined, document: extracted?.customer?.document || input.contactDocument || undefined },
    delivery,
    paymentMethod: extracted?.paymentMethod || undefined,
    items,
    rawOrderText,
    notes: notes || undefined,
    orderAction,
    contextUntil: transcript.contextUntil || undefined,
  },
} }];

// Solo se leen los mensajes NUEVOS: del día actual en America/Bogota y posteriores a `since`.
// `since` lo calcula la app: con un pedido abierto hoy (sin despachar) es el último mensaje que ya
// se leyó en ese pedido; sin pedido abierto, lo más reciente entre las 00:00 y el último despacho.
// Así nada ya registrado o despachado se vuelve a leer ni a sumar.
// Las notas de voz quedan como [AUDIO n] en su lugar cronológico y se transcriben después.
const input = $('Normalizar entrada').first().json;
const response = $input.first().json;
const context = $('Contexto del pedido').first().json;
// Si la app no respondió se lee todo el día y se ajusta el pedido abierto, como antes.
const contextOk = context.statusCode >= 200 && context.statusCode < 300;
const openOrder = contextOk ? context.body?.openOrder || null : null;
const since = contextOk && context.body?.since ? new Date(context.body.since) : null;
const raw = response.body?.messages;
const messages = Array.isArray(raw) ? raw : Array.isArray(raw?.messages) ? raw.messages : [];
const timeZone = 'America/Bogota';
const dayKey = (date) => {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const values = Object.fromEntries(parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
};
const parseDate = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  const date = Number.isFinite(numeric) ? new Date(numeric < 1e12 ? numeric * 1000 : numeric) : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};
const AUDIO_EXT = /\.(?:ogg|oga|opus|mp3|mpga|mpeg|m4a|wav|webm|aac|amr)(?:$|[?#])/i;
const IMAGE_EXT = /\.(?:jpe?g|png|gif|webp|heic)(?:$|[?#])/i;
const classify = (message) => {
  const urls = Array.isArray(message.attachments) ? message.attachments.filter((value) => typeof value === 'string') : [];
  const contentType = String(message.contentType || '').toLowerCase();
  const kind = String(message.messageType || message.type || '').toLowerCase();
  const audioMessage = contentType.startsWith('audio/') || /audio|voice|ptt/.test(kind);
  const imageMessage = contentType.startsWith('image/') || /image|photo/.test(kind);
  return urls.map((url) => ({
    url,
    kind: audioMessage || AUDIO_EXT.test(url) ? 'audio' : imageMessage || IMAGE_EXT.test(url) ? 'image' : 'other',
  }));
};

const today = dayKey(new Date());
const current = messages
  .map((message) => ({ ...message, parsedDate: parseDate(message.dateAdded || message.createdAt || message.dateUpdated) }))
  .filter((message) => message.parsedDate && dayKey(message.parsedDate) === today)
  .filter((message) => !since || message.parsedDate > since)
  .sort((a, b) => a.parsedDate - b.parsedDate);
const turns = [];
const images = [];
const audios = [];
for (const message of current) {
  const role = message.direction === 'inbound' ? 'CLIENTE' : 'FÉNIX J.A.';
  const inbound = message.direction === 'inbound';
  const body = typeof message.body === 'string' ? message.body.trim() : '';
  if (body) turns.push(`${role}: ${body}`);
  for (const attachment of classify(message)) {
    if (attachment.kind === 'image') {
      turns.push(`${role}: [IMAGEN ADJUNTA]`);
      if (inbound) images.push(attachment.url);
    } else if (attachment.kind === 'audio' && inbound) {
      const key = `AUDIO ${audios.length + 1}`;
      audios.push({ key, url: attachment.url, messageId: message.id || null });
      turns.push(`${role}: [${key}]`);
    } else if (attachment.kind === 'audio') {
      turns.push(`${role}: [NOTA DE VOZ DEL EQUIPO]`);
    } else {
      turns.push(`${role}: [ARCHIVO ADJUNTO]`);
    }
  }
}
const inboundMessages = current.filter((message) => message.direction === 'inbound');
const lastInbound = inboundMessages.at(-1);

return [{ json: {
  transcript: turns.join('\n'),
  turns: turns.length,
  messagesToday: current.length,
  imageUrls: [...new Set(images)].slice(-10),
  audios: audios.slice(-10),
  readStatus: response.statusCode,
  bogotaDay: today,
  inboundMessages: inboundMessages.length,
  contextOk,
  openOrder,
  // El siguiente llamado empieza después del último mensaje leído aquí.
  contextUntil: current.at(-1)?.parsedDate?.toISOString() || null,
  idempotencySeed: `${input.contactId}|${today}|${lastInbound?.id || lastInbound?.parsedDate?.toISOString() || "sin-mensaje"}`,
} }];

// La tool de GHL solo ordena procesar; crear o actualizar lo decide la app.
const webhook = $('Webhook').first().json;
const body = webhook.body || {};
const rawCustom = body.customData || body.custom_data || {};
let custom = rawCustom;
if (typeof rawCustom === 'string') {
  try { custom = JSON.parse(rawCustom); } catch (error) { custom = {}; }
}
const clean = (value) => value === undefined || value === null ? '' : String(value).trim();
const pick = (...values) => values.map(clean).find(Boolean) || '';
const normalized = {};
for (const source of [body, custom]) {
  if (!source || typeof source !== 'object') continue;
  for (const [key, value] of Object.entries(source)) {
    normalized[key.toLowerCase().replace(/[\s_]+/g, ' ').trim()] = value;
  }
}
const field = (...names) => pick(...names.map((name) => normalized[name]));

return [{
  json: {
    locationId: pick(body.locationId, custom.locationId, body.location?.id, body.location_id, custom.location_id),
    contactId: pick(body.contactId, custom.contactId, body.contact_id, body.contact?.id, custom.contact_id),
    contactName: pick(body.contactName, custom.contactName, body.full_name, custom.full_name, `${clean(body.first_name)} ${clean(body.last_name)}`),
    contactPhone: pick(body.contactPhone, custom.contactPhone, body.phone, custom.phone),
    contactDocument: pick(body.contactDocument, custom.contactDocument, field('documento de identidad', 'cedula', 'document')),
    contactAddress: pick(body.contactAddress, custom.contactAddress, field('direccion de envio', 'address1'), body.full_address),
  },
}];
